using Purview.Telemetry;

namespace Purview.EventSourcing;

/// <summary>
/// Provider-neutral event-store metrics.
/// </summary>
/// <remarks>
/// An implementation is generated by the Purview telemetry source generator. Every storage provider
/// records the same instruments with the same tags, so a dashboard built against one provider keeps
/// working against another. Instrument and tag names are a public contract: changing one breaks the
/// queries and alerts built on it.
/// </remarks>
// InstrumentPrefix is set explicitly: the generator otherwise derives it from the interface name,
// publishing "event_store_metrics.save.duration".
[Meter("Purview.EventSourcing", InstrumentPrefix = "purview.eventsourcing")]
public interface IEventStoreMetrics
{
	/// <summary>
	/// Records how long a save took, and how it ended.
	/// </summary>
	/// <param name="milliseconds">The elapsed time, in milliseconds.</param>
	/// <param name="aggregateType">The aggregate type name.</param>
	/// <param name="outcome">
	/// <c>written</c>, <c>no-changes</c>, <c>already-applied</c>, or the failure case name.
	/// </param>
	[Histogram("save.duration")]
	void SaveDuration(
		[InstrumentMeasurement] double milliseconds,
		[Tag("aggregate.type")] string aggregateType,
		[Tag("outcome")] string outcome
	);

	/// <summary>
	/// Records how long reconstituting an aggregate took.
	/// </summary>
	/// <param name="milliseconds">The elapsed time, in milliseconds.</param>
	/// <param name="aggregateType">The aggregate type name.</param>
	[Histogram("get.duration")]
	void GetDuration([InstrumentMeasurement] double milliseconds, [Tag("aggregate.type")] string aggregateType);

	/// <summary>
	/// Counts events appended to a stream by a successful save.
	/// </summary>
	/// <param name="count">The number of events appended.</param>
	/// <param name="aggregateType">The aggregate type name.</param>
	[Counter("events.appended")]
	void EventsAppended([InstrumentMeasurement] int count, [Tag("aggregate.type")] string aggregateType);
}
